pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(c));
        uint256 ts = bound(seed, 1, type(uint64).max);
        vm.warp(ts);
        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() { ok = true; } catch { ok = false; }
        assertTrue(ok, "play with exact ticket price must not revert");
    }
    receive() external payable {}
}
